const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='reference-studio-v1', defaults=['상품명·브랜드·내용량','원재료명·원산지','식품 유형·제조원·판매원','소비기한·보관 방법','알레르기·주의 사항','배송 방식·교환/반품 안내'];
const template=[['01','첫 화면','브랜드·상품명·핵심 가치','실상품 전체 이미지, 정확한 표기'],['02','맛과 식감','실제 확인된 표현만 사용','질감이 드러나는 실제 제품 사진'],['03','원재료','원재료와 원산지 확인','원물 사진은 실제 원재료만'],['04','차별점','검증된 특징 2~3개','짧은 카피와 근거를 함께'],['05','활용 장면','먹는 방법·페어링','실상품을 보존한 배경 연출'],['06','보관·배송','보관법·배송 방식','아이콘과 간결한 안내'],['07','상품 정보','표시사항·알레르기 정보','읽기 쉬운 표'],['08','구매 마무리','핵심 가치 재확인·구매 안내','실상품 사진과 명료한 CTA']];
let db=load(), current=db.current||null, shot=null;
function load(){try{return JSON.parse(localStorage.getItem(KEY))||{records:[],products:[]}}catch{return {records:[],products:[]}}}function save(){db.current=current;try{localStorage.setItem(KEY,JSON.stringify(db))}catch{status('저장 공간이 가득 찼습니다. 스크린샷을 줄이거나 JSON을 내보내세요.')}}
function status(m,ok=false){$('#status').textContent=m;$('#status').className='status show'+(ok?' ok':'')}
function safeUrl(raw){let u=new URL(raw);if(!/^https?:$/.test(u.protocol))throw Error('http 또는 https URL만 입력할 수 있습니다.');if(['localhost','127.0.0.1','0.0.0.0','::1'].includes(u.hostname))throw Error('공개 URL을 입력해 주세요.');return u.href}
function extract(html,url,source){const doc=new DOMParser().parseFromString(html,'text/html');const inline=[...doc.querySelectorAll('[style]')].map(x=>x.getAttribute('style')).join(';');doc.querySelectorAll('script,style,noscript,svg,nav,footer,header').forEach(x=>x.remove());const headings=[...doc.querySelectorAll('main h1,main h2,main h3,article h1,article h2,article h3,h1,h2,h3')].map((e,i)=>({level:e.tagName,text:e.textContent.trim().replace(/\s+/g,' ').slice(0,100)})).filter(x=>x.text.length>1).filter((x,i,a)=>a.findIndex(y=>y.text===x.text)===i).slice(0,24);const meta=[...doc.querySelectorAll('meta[property="og:title"],meta[name="description"]')].map(e=>e.content).filter(Boolean);const text=doc.body?.textContent?.replace(/\s+/g,' ')||'';const css=[...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi)].map(x=>x[1]).join('\n');const color=[...new Set((inline+' '+css).match(/#[0-9a-fA-F]{3,8}\b|rgba?\([^)]*\)/g)||[])].slice(0,12);const fonts=[...new Set([...((inline+' '+css).matchAll(/font-family\s*:\s*([^;}]+)/gi))].map(m=>m[1].trim().slice(0,80)))].slice(0,5);const imgs=[...doc.querySelectorAll('img')].map(x=>({src:x.getAttribute('src'),w:Number(x.getAttribute('width'))||null,h:Number(x.getAttribute('height'))||null,alt:x.alt||''}));const ratios=imgs.filter(x=>x.w&&x.h).slice(0,12).map(x=>`${x.w}:${x.h}`);const trust=['HACCP','인증','후기','리뷰','원산지','제조','검사','교환','반품','배송'].filter(w=>text.includes(w));const phrases=headings.map(x=>x.text).join(' ');const tone=phrases?(/!|맛있|특별|프리미엄|최고/.test(phrases)?'강조·감성 표현이 제목에서 관찰됨 (추정)':'설명 중심 제목이 관찰됨 (추정)'):'확인 필요';let title=doc.title?.trim()||meta[0]||new URL(url).hostname;return {url,title,source,at:new Date().toISOString(),headings,meta,color,fonts,imageCount:imgs.length,ratios,trust,tone,textSample:text.slice(0,1800),notes:[],screenshot:shot||null}}
async function analyze(){let url;try{url=safeUrl($('#url').value.trim())}catch(e){status(e.message);return}$('#analyze').disabled=true;status('공개 HTML을 읽는 중입니다.');try{const res=await fetch(url,{mode:'cors',credentials:'omit',redirect:'follow'});if(!res.ok)throw Error(`HTTP ${res.status}`);const html=await res.text();if(!/<(?:html|body|main|article)[\s>]/i.test(html))throw Error('HTML 구조가 확인되지 않았습니다.');add(extract(html,url,'공개 HTML 직접 읽기'));status('HTML에서 확인 가능한 항목을 분석했습니다. 화면 렌더링과 외부 CSS는 별도 확인이 필요합니다.',true)}catch(e){status(`URL 자동 읽기 제한: ${e.message}. HTML 입력을 열어 페이지 소스를 붙여넣어 주세요.`);$('#pasteArea').classList.remove('hidden')}finally{$('#analyze').disabled=false}}
function add(r){r.version=1+Math.max(0,...db.records.filter(x=>x.url===r.url).map(x=>x.version||0));db.records.push(r);current=r;save();render()}
function mini(title,description){return `<div class="mini"><strong>${esc(title)}</strong><p>${esc(description)}</p></div>`}
function render(){const r=current;$('#target').textContent=r?.title||'URL을 입력해 주세요';$('#source').textContent=r?`${r.source} · ${new URL(r.url).hostname}`:'확인된 근거 없음';$('#sectionCount').textContent=`${r?.headings?.length||0}개`;$('#version').textContent=r?`v${r.version}`:'—';$('#date').textContent=r?new Date(r.at).toLocaleString('ko-KR'):'분석 전';$('#url').value=r?.url||$('#url').value;
$('#sections').innerHTML=r?.headings?.length?r.headings.map((h,i)=>`<div class="sectionitem"><span class="number">${String(i+1).padStart(2,'0')}</span><div><strong>${esc(h.text)}</strong><p>${esc(h.level)} 제목 · 실제 화면 순서는 동적 콘텐츠에 따라 달라질 수 있음</p></div></div>`).join(''):mini('확인 필요','HTML의 제목 구조를 확인해야 섹션 순서를 표시할 수 있습니다.');$('#sectionEvidence').textContent=r?'HTML 제목 순서':'확인 필요';
$('#patterns').innerHTML=[mini('구조',r?.headings?.length?`${r.headings.length}개 제목 · ${r.headings.slice(0,3).map(x=>x.text).join(' → ')}`:'확인 필요'),mini('카피 톤',r?.tone||'확인 필요'),mini('정보 배치',r?.headings?.length?'제목 순서 확인됨 · 실제 시각 배치는 캡처 확인 필요':'확인 필요'),mini('신뢰 요소',r?.trust?.length?r.trust.join(' · ')+' (본문 키워드 출현, 사실성 검증 필요)':'확인 필요')].join('');
$('#apply').innerHTML=[mini('순서와 리듬','확인된 섹션 순서와 정보 밀도만 새 상품의 특성에 맞게 재구성'),mini('시각 요소',r?.color?.length?'관찰된 색상 중 브랜드와 어울리는 색을 선정해 토큰화':'색상은 확인 필요 · 브랜드 팔레트 우선'),mini('신뢰 형식','원산지·표시사항·보관 정보의 제시 방식을 참고하고 내용은 우리 상품으로 재검증')].join('');$('#avoid').innerHTML=[mini('타사 고유 자산','로고·패키지·제품 사진·고유 카피를 복제하지 않습니다.'),mini('미확인 주장','인증, 효능, 원산지, 가격, 후기, 배송 혜택은 증빙 없이 적용하지 않습니다.'),mini('실상품 변형','상품 형태·라벨·로고·색·비율을 생성 이미지로 재구성하지 않습니다.')].join('');
$('#colors').innerHTML=r?.color?.length?`<div class="swatches">${r.color.map(c=>`<span class="swatch" title="${esc(c)}" style="background:${esc(c)}"></span>`).join('')}</div><p>${esc(r.color.join(', '))}<br><small>HTML 내 스타일 값 · 실제 사용 비중 확인 필요</small></p>`:'<p>확인 필요 · 외부 CSS와 화면 캡처를 확인하세요.</p>';
$('#typography').textContent=r?.fonts?.length?`HTML에 선언된 글꼴: ${r.fonts.join(' / ')}. 실제 렌더링 글꼴·크기·굵기는 확인 필요.`:'확인 필요 · 외부 CSS 및 실제 렌더링 글꼴은 추출되지 않았습니다.';$('#images').textContent=r?`img 요소 ${r.imageCount}개. ${r.ratios.length?'명시 크기 비율: '+r.ratios.join(', '):'이미지 실제 비율 확인 필요'}. 화면상 정보 배치 확인 필요.`:'확인 필요';$('#copy').textContent=r?`${r.tone}. ${r.trust.length?'본문 키워드: '+r.trust.join(', '):'신뢰 요소 확인 필요'}. 실제 주장과 증빙은 확인 필요.`:'확인 필요';
$('#food').innerHTML=defaults.map(x=>`<div class="check"><span class="tag warn">확인 필요</span>${esc(x)}</div>`).join('');$('#capture').innerHTML=r?.screenshot?`<img alt="첨부한 레퍼런스 캡처" src="${r.screenshot}">`:'<div class="empty">▧<strong>캡처 이미지가 없습니다</strong>스크린샷을 첨부하여 보관하세요.<small>URL만으로는 타 사이트 화면을 캡처할 수 없습니다.</small></div>';
$('#systemContent').innerHTML=[mini('레이아웃','모바일 세로형 · 섹션별 독립 860px × 1200px 이상 · 8개 섹션'),mini('팔레트',r?.color?.length?r.color.slice(0,5).join(' · ')+' (후보, 검수 필요)':'브랜드 색상 확인 필요'),mini('타입',r?.fonts?.length?r.fonts.join(' / ')+' (후보)':'한글 가독성 중심 · 레퍼런스 글꼴 확인 필요'),mini('간격과 정보 위계','헤드라인 → 근거/상품 사진 → 상세 설명 → 주의 정보'),mini('사진 처리','실제 상품·패키지·로고 픽셀을 보존하고 배경만 편집')].join('');$('#guidelines').innerHTML=[mini('1 · 근거',`레퍼런스 URL: ${r?.url||'확인 필요'} · 출처: ${r?.source||'확인 필요'}`),mini('2 · 카피','사실로 확인된 맛·식감·원산지·중량만 표현. 미확인 문구는 확인 필요 표시'),mini('3 · 이미지','실상품 사진을 우선 사용. 배경 생성 시 제품 영역을 마스킹해 보존'),mini('4 · 출력','8개 섹션을 각각 860px 너비·1200px 이상 높이로 저장'),mini('5 · 검수','상품 정보와 표시사항, 이미지 일치, 잘림, 텍스트 판독성 확인')].join('');
$('#templates').innerHTML=template.map(([n,t,c,v])=>`<div class="sectionitem" style="margin:8px 0"><span class="number">${n}</span><div><strong>${esc(t)}</strong><p>카피: ${esc(c)}<br>이미지: ${esc(v)}<br>출력: 860 × 1200px 이상, 독립 파일</p></div></div>`).join('');$('#prompt').value=`식품 상품 상세페이지용 세로형 섹션 이미지 1장을 제작한다. 출력 크기: 가로 860px, 높이 1200px 이상. 섹션 목표와 카피는 해당 템플릿을 따른다. 제공된 실제 상품 사진과 패키지, 로고의 형태·색상·라벨·문구·비율은 원본 그대로 보존하고 제품 외곽을 자르지 않는다. 제품 영역을 보호한 채 배경과 소품만 생성·수정한다. 실제 상품과 다른 원물이나 제품을 만들지 않는다. 주장·표시사항이 확인되지 않으면 '확인 필요'로 남긴다. 레퍼런스의 구조적 패턴만 참고하고 타사 고유 디자인을 복제하지 않는다. 레퍼런스 URL: ${r?.url||'확인 필요'}.`;
$('#qa').innerHTML=['상품·패키지·로고 원본 보존','제품의 모든 외곽이 잘리지 않음','섹션마다 독립 이미지 1장','각 이미지 가로 860px · 높이 1200px 이상','원재료·원산지·내용량 정확성','맛·식감·인증·효능 근거 확인','보관법·소비기한·배송 정보 확인','타사 로고·고유 카피·이미지 복제 없음','모바일에서 글자 판독 가능'].map(x=>`<label class="check"><input type="checkbox"> ${esc(x)}</label>`).join('');renderHistory()}
function renderHistory(){const groups={};db.records.forEach(r=>(groups[r.url]??=[]).push(r));$('#history').innerHTML=Object.entries(groups).reverse().map(([u,rows])=>`<div class="historyrow"><div><strong>${esc(rows.at(-1).title)}</strong><small>${esc(u)} · ${rows.length}개 버전</small></div><button class="secondary" data-open="${esc(u)}">열기</button></div>`).join('')||mini('이력 없음','첫 URL 분석 후 이곳에 저장됩니다.');let opts=db.records.map((r,i)=>`<option value="${i}">${esc(new URL(r.url).hostname)} · v${r.version} · ${new Date(r.at).toLocaleDateString('ko-KR')}</option>`).join('');$('#compareA').innerHTML=opts;$('#compareB').innerHTML=opts;$('#compareA').selectedIndex=Math.max(0,db.records.length-2);$('#compareB').selectedIndex=Math.max(0,db.records.length-1)}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));['analysis','system','templates','history'].forEach(v=>$('#'+v+'View').classList.toggle('hidden',b.dataset.view!==v))});$('#analyze').onclick=analyze;$('#url').onkeydown=e=>{if(e.key==='Enter')analyze()};$('#pasteToggle').onclick=()=>$('#pasteArea').classList.toggle('hidden');$('#analyzeHtml').onclick=()=>{try{let u=safeUrl($('#url').value.trim());let h=$('#html').value;if(h.trim().length<100)throw Error('HTML 내용이 너무 짧습니다.');add(extract(h,u,'사용자 제공 HTML'));status('붙여넣은 HTML을 분석했습니다. 실제 화면과 차이가 있을 수 있습니다.',true)}catch(e){status(e.message)}};
$('#screenshot').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>2e6){status('스크린샷은 2MB 이하로 줄여 주세요.');return}let reader=new FileReader;reader.onload=()=>{shot=reader.result;if(current){current.screenshot=shot;save();render()}else status('분석을 먼저 실행하면 캡처가 해당 버전에 저장됩니다.')};reader.readAsDataURL(f)};
function download(name,obj){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}$('#export').onclick=()=>download('product-reference-settings.json',{schema:'reference-studio/v1',exportedAt:new Date().toISOString(),records:db.records,products:db.products,current});$('#import').onchange=async e=>{try{let o=JSON.parse(await e.target.files[0].text());if(o.schema!=='reference-studio/v1'||!Array.isArray(o.records))throw Error('지원하지 않는 JSON 형식입니다.');db.records=o.records.filter(x=>x&&typeof x.url==='string'&&Array.isArray(x.headings)).slice(-100);db.products=Array.isArray(o.products)?o.products:[];current=o.current&&typeof o.current.url==='string'?o.current:db.records.at(-1)||null;save();render();status('JSON 설정을 불러왔습니다.',true)}catch(err){status(`불러오기 실패: ${err.message}`)}};
$('#copyProduct').onclick=()=>{if(!current){status('먼저 레퍼런스를 분석해 주세요.');return}let item={id:Date.now(),referenceUrl:current.url,referenceVersion:current.version,name:'',sections:template.map(([n,t])=>({number:n,title:t,status:'확인 필요'})),image:{width:860,minHeight:1200,independent:true,preserveRealProduct:true,backgroundOnly:true},createdAt:new Date().toISOString()};db.products.push(item);save();$('#productWork').classList.remove('hidden');$('#productName').focus();status('새 상품 작업 설정을 만들었습니다. 이름을 입력하고 JSON으로 내보낼 수 있습니다.',true)};$('#productName').oninput=e=>{if(db.products.length){db.products.at(-1).name=e.target.value;save()}};$('#copyJson').onclick=async()=>{if(!current){status('먼저 분석 결과를 만드세요.');return}try{await navigator.clipboard.writeText(JSON.stringify({reference:current,designRules:{width:860,minHeight:1200,independent:true,preserveRealProduct:true,backgroundOnly:true},templates:template},null,2));status('설정을 클립보드에 복사했습니다.',true)}catch{status('복사가 차단되었습니다. JSON 내보내기를 이용해 주세요.')}};$('#copyPrompt').onclick=async()=>{try{await navigator.clipboard.writeText($('#prompt').value);status('프롬프트를 복사했습니다.',true)}catch{status('복사가 차단되었습니다. 텍스트를 직접 선택해 주세요.')}};
$('#history').onclick=e=>{let b=e.target.closest('[data-open]');if(!b)return;current=db.records.filter(x=>x.url===b.dataset.open).at(-1);save();render();document.querySelector('[data-view="analysis"]').click()};$('#compare').onclick=()=>{let a=db.records[Number($('#compareA').value)],b=db.records[Number($('#compareB').value)];if(!a||!b){$('#diff').textContent='비교할 버전이 없습니다.';return}if(a.url!==b.url){$('#diff').textContent='같은 URL의 버전 두 개를 선택하세요.';return}let fields=[['섹션 순서',a.headings.map(x=>x.text).join(' → '),b.headings.map(x=>x.text).join(' → ')],['색상',a.color.join(', '),b.color.join(', ')],['글꼴',a.fonts.join(', '),b.fonts.join(', ')],['이미지 개수',a.imageCount,b.imageCount],['신뢰 키워드',a.trust.join(', '),b.trust.join(', ')]];$('#diff').innerHTML=fields.map(([name,x,y])=>mini(name,x===y?`변경 없음 · ${x||'확인 필요'}`:`v${a.version}: ${x||'확인 필요'} → v${b.version}: ${y||'확인 필요'}`)).join('')};render();
